import type { Choices, SuggestionOrChoiceType } from './Choice'
import type { StringColumnType } from './String'
import type { Typed } from '../Column'
import type { TableName } from '../Table'
import type { choiceDropdownType } from './Choice'

/**
 * URL format validation (advisory only):
 * - Should start with http:// or https://
 * - Followed by domain and optional path
 * Note: Format hints are not strictly enforced by TypeScript
 *
 * `(string & {})` keeps autocomplete for http(s):// while still accepting any
 * string, since some URL-labeled fields (e.g. sys_ui_page.endpoint) hold
 * relative values like 'sn_appstore_store.do' rather than absolute URLs.
 */
type UrlColumnTypeFormat = `http://${string}` | `https://${string}` | (string & {})

export type UrlColumnType<
    TChoices extends Choices<string> = Choices<string>,
    Dropdown extends choiceDropdownType = choiceDropdownType,
    Type extends SuggestionOrChoiceType<Dropdown, TChoices> & UrlColumnTypeFormat = SuggestionOrChoiceType<
        Dropdown,
        TChoices
    > &
        UrlColumnTypeFormat,
    Default extends Type = Type,
    ReferenceSchema extends TableName = TableName,
> = StringColumnType<TChoices, Dropdown, Type, Default, ReferenceSchema>

/**
 * A Column for a URL type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @group Table/Columns
 */
export function UrlColumn<
    const TChoices extends Choices<string>,
    const Type extends SuggestionOrChoiceType<Dropdown, TChoices> & UrlColumnTypeFormat,
    const Default extends Type,
    const C extends UrlColumnType<TChoices, Dropdown, Type, Default, TableName>,
    const Dropdown extends choiceDropdownType = 'none',
>(config: C & UrlColumnType<TChoices, Dropdown, Type, Default, TableName>) {
    return config as Typed<Type, C>
}
